# --- 매니저를 만든다 ---

public class BusinessHoursAuthorizationManager
        implements AuthorizationManager<RequestAuthorizationContext> {
    private final Clock clock;

    @Override
    public AuthorizationDecision check(Supplier<Authentication> auth,
            RequestAuthorizationContext context) {
        LocalTime now = LocalTime.now(clock);
        boolean open = !now.isBefore(LocalTime.of(9, 0))
                && now.isBefore(LocalTime.of(18, 0));
        System.out.println(">>> now=" + now + " open=" + open);
        return new AuthorizationDecision(open);
    }
}

#   단위 테스트가 된다

@Test
void 업무시간에만_통과한다() {
    Authentication admin = UsernamePasswordAuthenticationToken.authenticated(
            "a", null, List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));

    for (String time : List.of("08:59", "09:00", "17:59", "18:00")) {
        Clock fixed = Clock.fixed(
                LocalDateTime.of(2026, 9, 9, Integer.parseInt(time.substring(0,2)),
                        Integer.parseInt(time.substring(3)))
                        .atZone(ZoneId.systemDefault()).toInstant(),
                ZoneId.systemDefault());
        var manager = new BusinessHoursAuthorizationManager(fixed);
        System.out.println(time + " -> " + manager.check(() -> admin, null));
    }
}

