@Bean
Advisor businessHoursAdvisor(BusinessHoursAuthorizationManager manager) {
    JdkRegexpMethodPointcut pointcut = new JdkRegexpMethodPointcut();
    pointcut.setPattern(".*AdminService.*");
    return new AuthorizationManagerBeforeMethodInterceptor(
            pointcut, (auth, invocation) -> manager.check(auth, null));
}

